// A hairline at any size: the sheet's divider is too thin to scale with the lockup.
function Divider() {
  return (
    <line
      x1="166.57"
      x2="166.57"
      y1="0"
      y2="79.44"
      stroke="currentColor"
      strokeWidth="1"
      vectorEffect="non-scaling-stroke"
    />
  );
}

/** The C9 symbol, for icon-sized slots. */
export function CodenineMark(props: SVGProps<SVGSVGElement>) {
  return (
    <svg {...props} viewBox={`0 0 ${SYMBOL_WIDTH} 100`} xmlns="http://www.w3.org/2000/svg">
      <path d={SYMBOL_PATH} fill="currentColor" />
    </svg>
  );
}

/** The divider and name that follow the symbol in the lockup. */
export function CodenineName(props: SVGProps<SVGSVGElement>) {
  return (
    <svg
      {...props}
      viewBox={`${SYMBOL_WIDTH} 0 ${LOCKUP_WIDTH - SYMBOL_WIDTH} 100`}
      xmlns="http://www.w3.org/2000/svg"
    >
      <Divider />
      <path d={NAME_PATH} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}

/** The full lockup: symbol, divider and name. */
export function CodenineWordmark(props: SVGProps<SVGSVGElement>) {
  return (
    <svg {...props} viewBox={`0 0 ${LOCKUP_WIDTH} 100`} xmlns="http://www.w3.org/2000/svg">
      <path d={SYMBOL_PATH} fill="currentColor" />
      <Divider />
      <path d={NAME_PATH} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}
